sp_widget.css:
.stat-card{
background:white;

border-radius:26px;

padding:34px;

height:190px;

position:relative;

overflow:hidden;

box-shadow:
0 18px 40px rgba(0,0,0,.06);

display:flex;

align-items:center;

gap:24px;

border-left:6px solid var(--accent);
}

.circle{
position:absolute;

right:-60px;

bottom:-60px;

width:180px;

height:180px;

border-radius:50%;

background:var(--accent);

opacity:.08;
}

.icon-box{

width:78px;

height:78px;

border-radius:22px;

display:flex;

align-items:center;

justify-content:center;

font-size:34px;

background:var(--accent);

color:white;

}

.stat-value{

font-size:58px;

font-weight:900;

color:#07184A;

line-height:1;
}

.stat-label{

margin-top:8px;

font-size:22px;

font-weight:700;

color:#7D89B0;
}

/* variations */

.employees{
--accent:#2F62F5;
}

.departments{
--accent:#00B87A;
}

.active{
--accent:#FF9F1C;
}

.inactive{
--accent:#A259FF;
}

sp_widget.script:
(function(){

var type =
$sp.getParameter('type') ||
options.type ||
'employees';

data.value=0;

var emp =
'x_1902481_employ_0_employee';

if(type=="employees"){

var ga=
new GlideAggregate(emp);

ga.addAggregate('COUNT');

ga.query();

if(ga.next())
data.value=
ga.getAggregate('COUNT');

data.label=
'Employees';

data.icon='👥';

data.class='employees';

}

else if(type=="departments"){

var dept=
new GlideAggregate(
'x_1902481_employ_0_department'
);

dept.addAggregate('COUNT');

dept.query();

if(dept.next())
data.value=
dept.getAggregate('COUNT');

data.label=
'Departments';

data.icon='🏢';

data.class='departments';

}

else if(type=="active"){

var gr=
new GlideAggregate(emp);

gr.addQuery(
'active',
true
);

gr.addAggregate('COUNT');

gr.query();

if(gr.next())
data.value=
gr.getAggregate('COUNT');

data.label=
'Active';

data.icon='🟢';

data.class='active';

}

else{

var gr=
new GlideAggregate(emp);

gr.addQuery(
'active',
false
);

gr.addAggregate('COUNT');

gr.query();

if(gr.next())
data.value=
gr.getAggregate('COUNT');

data.label=
'Inactive';

data.icon='🔴';

data.class='inactive';

}

})();
